"""The oracles of the R0 tasks written a second time, in Python, from the task descriptions: a comparison helper only (docs/design.md section 14).
scripts/crosscheck.py grades a table of these answers with the cancho grader; nothing builds, grades or trains with this file."""
"""Task definitions, batch A. Each task: name, params [(name, type)], ret, desc, py (the oracle, independent of ref),
args (explicit argument tuples, edge cases included), ref (the cancho reference). See docs/design.md section 12."""
import math

def T(name, params, ret, desc, py, args, examples=3):
    return dict(name=name, py=py)

def grid(*vals):
    out = [()]
    for v in vals:
        out = [o + (x,) for o in out for x in v]
    return out

def tdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b > 0) else -q
NEG = [-1000000000, -17, -3, -2, -1]
POS = [0, 1, 2, 3, 4, 5, 7, 10, 16, 17, 99, 100, 101, 255, 1000, 65535, 999999, 1000000000]
ALLI = NEG + POS
TASKS = [T('abs_diff', [('a', 'int'), ('b', 'int')], 'int', 'The absolute difference |a - b|. Domain: |a| and |b| are at most 1000000000.', lambda a, b: abs(a - b), grid(ALLI, ALLI)), T('sign', [('x', 'int')], 'int', 'The sign of x: -1 if x is negative, 0 if x is zero, 1 if x is positive. Any int, including the extremes.', lambda x: (x > 0) - (x < 0), grid(ALLI + [-(1 << 63) + 1, (1 << 63) - 1])), T('max3', [('a', 'int'), ('b', 'int'), ('c', 'int')], 'int', 'The largest of the three arguments. Any int.', lambda a, b, c: max(a, b, c), grid([-5, 0, 3, 9], [-5, 0, 3, 9], [-5, 0, 3, 9, 1 << 40])), T('median3', [('a', 'int'), ('b', 'int'), ('c', 'int')], 'int', 'The median of the three arguments: the value that is left in the middle when they are sorted. Ties are fine: median3(2, 2, 9) is 2. Any int.', lambda a, b, c: sorted([a, b, c])[1], grid([-5, 0, 3, 9], [-5, 0, 3, 9], [-5, 0, 3, 9, 1 << 40])), T('is_even', [('x', 'int')], 'bool', 'True when x is even. Any int, negative ones included: -4 is even and -3 is not. (% on a negative int can be negative; compare it with == 0 only.)', lambda x: x % 2 == 0, grid(ALLI + [-(1 << 63) + 1, (1 << 63) - 1])), T('digit_sum', [('n', 'int')], 'int', 'The sum of the decimal digits of n. Domain: 0 <= n <= 9223372036854775807. digit_sum(0) is 0.', lambda n: sum(map(int, str(n))), grid(POS + [123456789, 9223372036854775807, 1000000007])), T('count_digits', [('n', 'int')], 'int', 'How many decimal digits n has. Domain: 0 <= n <= 9223372036854775807. count_digits(0) is 1.', lambda n: len(str(n)), grid(POS + [9, 10, 99999, 100000, 9223372036854775807, 1000000000000])), T('reverse_digits', [('n', 'int')], 'int', 'The decimal digits of n in reverse order, as a number: 1230 becomes 321 (leading zeros vanish). Domain: 0 <= n <= 1000000000.', lambda n: int(str(n)[::-1]), grid(POS + [120, 1230, 100000, 123456789, 987654321])), T('is_palindrome_num', [('n', 'int')], 'bool', 'True when the decimal digits of n read the same forwards and backwards. Domain: 0 <= n <= 1000000000. 0 is a palindrome; 10 is not.', lambda n: str(n) == str(n)[::-1], grid(POS + [11, 121, 1221, 12321, 12345, 1000000001 - 2, 999999999])), T('factorial', [('n', 'int')], 'int', 'n! = 1 * 2 * ... * n, with 0! = 1. Domain: 0 <= n <= 20 (20! fits an int; overflow is an error, not a wrap).', lambda n: math.factorial(n), grid(list(range(0, 21)))), T('fib', [('n', 'int')], 'int', 'The n-th Fibonacci number with fib(0) = 0, fib(1) = 1, fib(2) = 1. Domain: 0 <= n <= 90 (fib(90) fits an int; computing past the answer can overflow).', lambda n: [0, 1][n] if n < 2 else _fib(n), grid(list(range(0, 91)))), T('sum_to', [('n', 'int')], 'int', '1 + 2 + ... + n, and 0 when n is 0. Domain: 0 <= n <= 4000000000, so the answer fits an int but a loop of that length is far too slow: use the formula.', lambda n: n * (n + 1) // 2, grid([0, 1, 2, 3, 10, 100, 12345, 1000000, 65536, 1000000000, 3000000000, 4000000000])), T('collatz_steps', [('n', 'int')], 'int', 'How many steps the Collatz process takes to reach 1 from n: if n is even halve it, otherwise replace it with 3n + 1, counting each step. collatz_steps(1) is 0. Domain: 1 <= n <= 1000000.', lambda n: _collatz(n), grid([1, 2, 3, 6, 7, 9, 27, 97, 871, 6171, 77031, 837799, 999999, 1000000, 8, 64])), T('is_prime', [('n', 'int')], 'bool', 'True when n is a prime number. 0, 1 and negative numbers are not prime. Domain: -10 <= n <= 1000000.', lambda n: _isprime(n), grid(list(range(-10, 60)) + [97, 100, 7919, 7921, 104729, 999983, 999979 + 4, 1000000, 65537, 561, 1105])), T('count_divisors', [('n', 'int')], 'int', 'How many positive integers divide n exactly, 1 and n included. Domain: 1 <= n <= 100000.', lambda n: sum((1 for d in range(1, n + 1) if n % d == 0)), grid([1, 2, 3, 4, 6, 12, 16, 25, 36, 49, 60, 97, 100, 360, 720, 5040, 65536, 99991, 83160, 100000])), T('sum_proper_divisors', [('n', 'int')], 'int', 'The sum of the positive divisors of n that are smaller than n (1 included when n > 1). sum_proper_divisors(1) is 0. Domain: 1 <= n <= 100000.', lambda n: sum((d for d in range(1, n) if n % d == 0)), grid([1, 2, 3, 4, 6, 12, 28, 36, 97, 100, 496, 8128, 12496, 99991, 100000, 945, 220, 284])), T('is_perfect_square', [('n', 'int')], 'bool', 'True when n is the square of an integer. Negative numbers are not. Domain: -100 <= n <= 1000000000000.', lambda n: n >= 0 and math.isqrt(n) ** 2 == n, grid([-100, -1, 0, 1, 2, 3, 4, 8, 9, 15, 16, 17, 99, 100, 101, 999999999999, 1000000000000, 999999000001, 999998000001, 999998000000, 4503599627370496 // 10000])), T('pow_int', [('base', 'int'), ('exp', 'int')], 'int', 'base raised to exp. Domain: -10 <= base <= 10 and 0 <= exp <= 18, so the answer always fits an int. base^0 is 1 for every base, 0 included.', lambda b, e: b ** e, grid(list(range(-10, 11)), list(range(0, 19)))), T('ceil_div', [('a', 'int'), ('b', 'int')], 'int', 'a divided by b, rounded up to the next whole number. Domain: 0 <= a <= 1000000000000 and 1 <= b <= 1000000000. ceil_div(0, 5) is 0.', lambda a, b: -(-a // b), grid([0, 1, 2, 5, 6, 7, 99, 100, 101, 1000000000000], [1, 2, 3, 5, 7, 10, 100, 1000000000])), T('round_up_to', [('x', 'int'), ('m', 'int')], 'int', 'The smallest multiple of m that is at least x. Domain: 0 <= x <= 1000000000000 and 1 <= m <= 1000000. round_up_to(0, 8) is 0 and round_up_to(16, 8) is 16.', lambda x, m: -(-x // m) * m, grid([0, 1, 7, 8, 9, 15, 16, 17, 1000, 999999999999, 1000000000000], [1, 2, 8, 10, 4096, 1000000])), T('popcount', [('n', 'int')], 'int', 'How many 1 bits n has in binary. Domain: 0 <= n <= 9223372036854775807.', lambda n: bin(n).count('1'), grid(POS + [255, 256, 1023, 1 << 40, (1 << 62) - 1, (1 << 63) - 1, 6148914691236517205 & (1 << 63) - 1])), T('is_power_of_two', [('n', 'int')], 'bool', 'True when n is 1, 2, 4, 8, ... Zero and negative numbers are not powers of two. Any int.', lambda n: n > 0 and n & n - 1 == 0, grid(ALLI + [3, 6, 8, 9, 12, 64, 63, 65, 1 << 40, (1 << 40) + 1, 1 << 62, (1 << 63) - 1, -(1 << 62)])), T('bit_length', [('n', 'int')], 'int', 'How many binary digits n needs: 1 for 1, 2 for 2 and 3, 3 for 4 to 7, and 0 for 0. Domain: 0 <= n <= 9223372036854775807.', lambda n: n.bit_length(), grid(POS + [255, 256, 1 << 40, (1 << 62) - 1, 1 << 62, (1 << 63) - 1])), T('days_in_month', [('year', 'int'), ('month', 'int')], 'int', 'The number of days in the given month (1 = January ... 12 = December) of the given year in the Gregorian calendar, February of a leap year having 29. Domain: 1 <= year <= 9999, 1 <= month <= 12.', lambda y, m: [31, 29 if y % 4 == 0 and (y % 100 != 0 or y % 400 == 0) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1], grid([1, 4, 100, 400, 1900, 1999, 2000, 2023, 2024, 2100, 9999], list(range(1, 13)))), T('triangle_kind', [('a', 'int'), ('b', 'int'), ('c', 'int')], 'int', 'Classify a triangle with side lengths a, b, c: 0 when the sides cannot form a triangle (any side is not positive, or the longest side is at least the sum of the other two), 1 when all three sides are equal, 2 when exactly two are equal, 3 when all are different. Domain: all sides between -5 and 1000000000.', lambda a, b, c: 0 if min(a, b, c) <= 0 or max(a, b, c) * 2 >= a + b + c else 1 if a == b == c else 2 if len({a, b, c}) == 2 else 3, grid([-5, 0, 1, 2, 3, 4, 5, 10, 1000000000], [-5, 0, 1, 2, 3, 4, 5, 10, 1000000000], [-5, 0, 1, 2, 3, 4, 5, 10, 1000000000])), T('fizzbuzz_code', [('n', 'int')], 'int', 'For n >= 1: 15 when n is divisible by both 3 and 5, 3 when only by 3, 5 when only by 5, and 0 otherwise. Domain: 1 <= n <= 1000000000.', lambda n: 15 if n % 15 == 0 else 3 if n % 3 == 0 else 5 if n % 5 == 0 else 0, grid(list(range(1, 31)) + [45, 99, 100, 101, 999999999, 1000000000, 1000000000 - 5])), T('mod_floor', [('a', 'int'), ('b', 'int')], 'int', 'The remainder of a divided by b that is never negative: always in 0..b-1, even when a is negative (mod_floor(-1, 5) is 4). Domain: |a| <= 1000000000000 and 1 <= b <= 1000000000.', lambda a, b: a % b, grid([-1000000000000, -100, -11, -10, -5, -1, 0, 1, 5, 10, 11, 100, 1000000000000], [1, 2, 3, 5, 10, 7, 1000000000])), T('floor_div', [('a', 'int'), ('b', 'int')], 'int', 'a divided by b, rounded toward negative infinity: floor_div(7, 2) is 3, floor_div(-7, 2) is -4. Domain: |a| <= 1000000000000 and 1 <= b <= 1000000000.', lambda a, b: a // b, grid([-1000000000000, -100, -11, -10, -5, -1, 0, 1, 5, 10, 11, 100, 1000000000000], [1, 2, 3, 5, 10, 7, 1000000000])), T('digital_root', [('n', 'int')], 'int', 'Add the decimal digits of n, repeat on the result until a single digit is left, and return it. digital_root(0) is 0 and digital_root(493193) is 2 (4+9+3+1+9+3 = 29, 2+9 = 11, 1+1 = 2). Domain: 0 <= n <= 9223372036854775807.', lambda n: n if n < 10 else 1 + (n - 1) % 9, grid(POS + [493193, 9223372036854775807, 999999999999, 18, 19])), T('hamming_bits', [('a', 'int'), ('b', 'int')], 'int', 'The number of bit positions where a and b differ in binary. Domain: 0 <= a, b <= 9223372036854775807.', lambda a, b: bin(a ^ b).count('1'), grid([0, 1, 2, 3, 255, 1 << 40, (1 << 63) - 1, 12345], [0, 1, 2, 3, 255, 1 << 40, (1 << 63) - 1, 54321])), T('sum_squares_to', [('n', 'int')], 'int', '1*1 + 2*2 + ... + n*n, and 0 when n is 0. Domain: 0 <= n <= 1000000 (a loop is fine).', lambda n: sum((i * i for i in range(1, n + 1))), grid([0, 1, 2, 3, 10, 100, 1000, 54321, 1000000])), T('binomial', [('n', 'int'), ('k', 'int')], 'int', 'The binomial coefficient C(n, k): the number of ways to choose k items from n. Domain: 0 <= k <= n <= 40. C(n, 0) and C(n, n) are 1.', lambda n, k: math.comb(n, k), [(n, k) for n in (0, 1, 2, 5, 10, 20, 30, 40) for k in range(0, n + 1)]), T('cube_root_floor', [('n', 'int')], 'int', 'The largest r with r * r * r <= n. Domain: 0 <= n <= 1000000000000000000.', lambda n: _icbrt(n), grid([0, 1, 2, 7, 8, 9, 26, 27, 28, 999, 1000, 1001, 123456789, 999999999999999999, 1000000000000000000, 1000000 ** 2 * 1000 - 1])), T('digit_sum_base', [('n', 'int'), ('b', 'int')], 'int', 'The sum of the digits of n written in base b. Domain: 0 <= n <= 1000000000000 and 2 <= b <= 10. digit_sum_base(255, 2) is 8.', lambda n, b: _dsb(n, b), grid([0, 1, 7, 8, 255, 256, 1000, 123456789, 1000000000000], [2, 3, 7, 8, 9, 10]))]

def _fib(n):
    a, b = (0, 1)
    for _ in range(n):
        a, b = (b, a + b)
    return a

def _collatz(n):
    s = 0
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        s += 1
    return s

def _isprime(n):
    if n < 2:
        return False
    return all((n % d for d in range(2, math.isqrt(n) + 1)))

def _icbrt(n):
    r = round(n ** (1 / 3))
    while r ** 3 > n:
        r -= 1
    while (r + 1) ** 3 <= n:
        r += 1
    return r

def _dsb(n, b):
    s = 0
    while n:
        s += n % b
        n //= b
    return s
